function brandingUpload(string $field,string $prefix):?string{if(empty($_FILES[$field])||(int)($_FILES[$field]['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;if((int)$_FILES[$field]['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Échec du téléversement de '.$field.'.');if((int)$_FILES[$field]['size']>5*1024*1024)throw new RuntimeException('Chaque image doit peser au maximum 5 Mo.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file((string)$_FILES[$field]['tmp_name']);$ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp','image/svg+xml'=>'svg'][$mime]??null;if(!$ext)throw new RuntimeException('Format refusé : utilisez PNG, JPG, WebP ou SVG.');$dir=dirname(__DIR__).'/uploads/branding';if(!is_dir($dir)&&!mkdir($dir,0775,true))throw new RuntimeException('Impossible de créer le dossier du branding.');$name=$prefix.'_'.date('YmdHis').'_'.bin2hex(random_bytes(5)).'.'.$ext;if(!move_uploaded_file((string)$_FILES[$field]['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Impossible d’enregistrer l’image.');return'uploads/branding/'.$name;}
function brandingColor(string $field,string $fallback):string{$value=strtolower(trim((string)($_POST[$field]??$fallback)));if(!preg_match('/^#[0-9a-f]{6}$/',$value))throw new RuntimeException('La couleur '.str_replace('_',' ',$field).' est invalide.');return$value;}
